#!/bin/sh
# Generated by FWShift: IP groups, network services and Cloud Firewall filtering rules for Zscaler Internet
# Access, created through the ZIA API. Read the report first: what is disabled or left out is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                                                   prints the calls, makes none
#   ZIA_BASE=https://api.zsapi.net/zia/api/v1 ZIA_TOKEN=... sh THIS_FILE      OneAPI (ZIdentity) token
#   ZIA_BASE=https://zsapi.<cloud>.net/api/v1 ZIA_SESSION=... sh THIS_FILE     JSESSIONID of a legacy session
#
# Nothing is activated: POST /status/activate is left to you. A legacy session that ends (logout, or its
# timeout) activates what was changed in it. The script stops at the first call that is refused, and at a name
# that is taken; what it created is in $JOURNAL (path, id, name), to delete again if need be.
set -eu
DRY_RUN="${DRY_RUN:-}"
JOURNAL="${JOURNAL:-zia-fwshift-created.txt}"
OUT=$(mktemp -d)
trap 'rm -rf "$OUT"' EXIT
if [ -z "$DRY_RUN" ]; then
  : "${ZIA_BASE:?set ZIA_BASE to the base URL of the ZIA API}"
  command -v jq >/dev/null || { echo "jq is needed" >&2; exit 1; }
  if [ -n "${ZIA_TOKEN:-}" ]; then AUTH="Authorization: Bearer $ZIA_TOKEN"
  elif [ -n "${ZIA_SESSION:-}" ]; then AUTH="Cookie: JSESSIONID=$ZIA_SESSION"
  else echo "set ZIA_TOKEN (OneAPI) or ZIA_SESSION (legacy API session)" >&2; exit 1; fi
fi
call() {  # call METHOD PATH [BODY-FILE]: the answer on stdout
  tries=0
  while :; do
    if [ -n "${3:-}" ]; then
      code=$(curl -sS -o "$OUT/answer" -D "$OUT/headers" -w '%{http_code}' -X "$1" -H "$AUTH" -H 'Content-Type: application/json' \
             --data-binary @"$3" "$ZIA_BASE$2")
    else
      code=$(curl -sS -o "$OUT/answer" -D "$OUT/headers" -w '%{http_code}' -X "$1" -H "$AUTH" "$ZIA_BASE$2")
    fi
    case "$code" in
      2??) cat "$OUT/answer"; sleep 1; return 0 ;;
      429) tries=$((tries+1)); [ "$tries" -le 5 ] || { echo "rate limited: $1 $2" >&2; return 1; }
           wait=$(sed -n 's/^[Rr]etry-[Aa]fter: *\([0-9]*\).*/\1/p' "$OUT/headers"); sleep "${wait:-2}" ;;
      *) echo "HTTP $code on $1 $2:" >&2; cat "$OUT/answer" >&2; return 1 ;;
    esac
  done
}
lookup() {  # lookup PATH NAME: the id of the entry of exactly that name, or nothing (the name is compared here)
  case "$1" in /firewallFilteringRules) query="" ;; *) query="?search=$(jq -rn --arg v "$2" '$v|@uri')&pageSize=1000" ;; esac
  answer=$(call GET "$1$query")
  printf '%s' "$answer" | jq -r --arg n "$2" '[.[] | select(.name == $n) | .id][0] // empty'
}
need() {  # need PATH NAME DRY-ID: the id of an entry the tenant must have
  if [ -n "$DRY_RUN" ]; then printf 'GET %s (name %s)\n' "$1" "$2" >&2; echo "$3"; return 0; fi
  id=$(lookup "$1" "$2")
  [ -n "$id" ] || { echo "not on the tenant: $2 ($1)" >&2; return 1; }
  echo "$id"
}
create() {  # create PATH NAME BODY-FILE DRY-ID: the id of the new entry; refuses a name that is taken
  if [ -n "$DRY_RUN" ]; then printf 'POST %s\n' "$1" >&2; cat "$3" >&2; printf '\n' >&2; echo "$4"; return 0; fi
  taken=$(lookup "$1" "$2")
  [ -z "$taken" ] || { echo "the name is taken: $2 ($1); nothing of it is changed" >&2; return 1; }
  answer=$(call POST "$1" "$3")
  id=$(printf '%s' "$answer" | jq -r '.id // empty')
  [ -n "$id" ] || { echo "no id in the answer to POST $1" >&2; return 1; }
  printf '%s %s %s\n' "$1" "$id" "$2" >> "$JOURNAL"
  echo "$id"
}

ID_1=$(need /locations 'lan' 1)
cat > "$OUT/2.json" <<FWSHIFT_JSON
{"name": "fws-tcp-502", "destTcpPorts": [{"start": 502}], "type": "CUSTOM", "description": "FWShift"}
FWSHIFT_JSON
ID_2=$(create /networkServices 'fws-tcp-502' "$OUT/2.json" 2)
ID_3=$(need /locations 'wan1' 3)
cat > "$OUT/4.json" <<FWSHIFT_JSON
{"name": "fws-tcp-23", "destTcpPorts": [{"start": 23}], "type": "CUSTOM", "description": "FWShift"}
FWSHIFT_JSON
ID_4=$(create /networkServices 'fws-tcp-23' "$OUT/4.json" 4)
cat > "$OUT/5.json" <<FWSHIFT_JSON
{"name": "fws-tcp-443", "destTcpPorts": [{"start": 443}], "type": "CUSTOM", "description": "FWShift"}
FWSHIFT_JSON
ID_5=$(create /networkServices 'fws-tcp-443' "$OUT/5.json" 5)
cat > "$OUT/6.json" <<FWSHIFT_JSON
{"name": "fws-udp-20000-20010-from-1024-65535", "destUdpPorts": [{"start": 20000, "end": 20010}], "srcUdpPorts": [{"start": 1024, "end": 65535}], "type": "CUSTOM", "description": "FWShift"}
FWSHIFT_JSON
ID_6=$(create /networkServices 'fws-udp-20000-20010-from-1024-65535' "$OUT/6.json" 6)
ID_7=$(need /networkServices 'ICMP_ANY' 7)
ID_8=$(need /locations 'wan2' 8)
cat > "$OUT/9.json" <<FWSHIFT_JSON
{"name": "fws-tcp-8080-8090", "destTcpPorts": [{"start": 8080, "end": 8090}], "type": "CUSTOM", "description": "FWShift"}
FWSHIFT_JSON
ID_9=$(create /networkServices 'fws-tcp-8080-8090' "$OUT/9.json" 9)
cat > "$OUT/10.json" <<FWSHIFT_JSON
{"name": "fws-tcp-22", "destTcpPorts": [{"start": 22}], "type": "CUSTOM", "description": "FWShift"}
FWSHIFT_JSON
ID_10=$(create /networkServices 'fws-tcp-22' "$OUT/10.json" 10)

# Firewall filtering rules, from order 1 on, in the order of the converted policy.
cat > "$OUT/11.json" <<FWSHIFT_JSON
{"name": "fws-firewall 1", "order": 1, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_1}}], "srcIps": ["192.168.127.10-192.168.127.20"], "destAddresses": ["172.16.40.5"], "nwServices": [{"id": ${ID_2}}]}
FWSHIFT_JSON
ID_11=$(create /firewallFilteringRules 'fws-firewall 1' "$OUT/11.json" 11)
cat > "$OUT/12.json" <<FWSHIFT_JSON
{"name": "fws-firewall 2", "order": 2, "rank": 7, "action": "BLOCK_DROP", "state": "ENABLED", "locations": [{"id": ${ID_3}}], "nwServices": [{"id": ${ID_4}}]}
FWSHIFT_JSON
ID_12=$(create /firewallFilteringRules 'fws-firewall 2' "$OUT/12.json" 12)
cat > "$OUT/13.json" <<FWSHIFT_JSON
{"name": "fws-firewall 3", "order": 3, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_3}}], "srcIps": ["198.51.100.0/24"], "destAddresses": ["192.168.127.50", "203.0.113.2"], "nwServices": [{"id": ${ID_5}}]}
FWSHIFT_JSON
ID_13=$(create /firewallFilteringRules 'fws-firewall 3' "$OUT/13.json" 13)
cat > "$OUT/14.json" <<FWSHIFT_JSON
{"name": "fws-firewall 4", "order": 4, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_1}}], "srcIps": ["192.168.127.30"], "nwServices": [{"id": ${ID_6}}]}
FWSHIFT_JSON
ID_14=$(create /firewallFilteringRules 'fws-firewall 4' "$OUT/14.json" 14)
cat > "$OUT/15.json" <<FWSHIFT_JSON
{"name": "fws-firewall 5", "order": 5, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_1}}], "nwServices": [{"id": ${ID_7}}]}
FWSHIFT_JSON
ID_15=$(create /firewallFilteringRules 'fws-firewall 5' "$OUT/15.json" 15)
cat > "$OUT/16.json" <<FWSHIFT_JSON
{"name": "fws-firewall 6", "order": 6, "rank": 7, "action": "ALLOW", "state": "DISABLED", "locations": [{"id": ${ID_8}}]}
FWSHIFT_JSON
ID_16=$(create /firewallFilteringRules 'fws-firewall 6' "$OUT/16.json" 16)
cat > "$OUT/17.json" <<FWSHIFT_JSON
{"name": "fws-firewall 7", "order": 7, "rank": 7, "action": "ALLOW", "state": "DISABLED", "description": "FWSHIFT inactive, see the report.", "locations": [{"id": ${ID_1}}]}
FWSHIFT_JSON
ID_17=$(create /firewallFilteringRules 'fws-firewall 7' "$OUT/17.json" 17)
cat > "$OUT/18.json" <<FWSHIFT_JSON
{"name": "fws-firewall 8", "order": 8, "rank": 7, "action": "ALLOW", "state": "DISABLED", "description": "FWSHIFT inactive, see the report.", "locations": [{"id": ${ID_8}}], "destAddresses": ["192.168.127.60-192.168.127.69", "198.51.100.60"], "nwServices": [{"id": ${ID_9}}]}
FWSHIFT_JSON
ID_18=$(create /firewallFilteringRules 'fws-firewall 8' "$OUT/18.json" 18)
cat > "$OUT/19.json" <<FWSHIFT_JSON
{"name": "fws-firewall 9", "order": 9, "rank": 7, "action": "BLOCK_DROP", "state": "ENABLED", "locations": [{"id": ${ID_1}}], "srcIps": ["192.168.127.200-192.168.127.250"]}
FWSHIFT_JSON
ID_19=$(create /firewallFilteringRules 'fws-firewall 9' "$OUT/19.json" 19)
cat > "$OUT/20.json" <<FWSHIFT_JSON
{"name": "fws-firewall 10", "order": 10, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_8}}], "destAddresses": ["192.168.127.60", "198.51.100.60"], "nwServices": [{"id": ${ID_10}}]}
FWSHIFT_JSON
ID_20=$(create /firewallFilteringRules 'fws-firewall 10' "$OUT/20.json" 20)
echo "done: nothing is active until the changes are activated (POST /status/activate)" >&2
